async ({ workspace: { search, edit } }) => {
  const a = await search('"value" in details ? readableValue(details.value) : text', { path: "src/durable/present.ts" });
  const b = await search("call(args: unknown): { title: string; body: string };", { path: "src/durable/present.ts" });
  const c = await search("      title: call.label ??", { path: "src/durable/present.ts", contextLines: 10 });
  const m = c.matches[0];
  const joinLine = m.after.find((x: any) => x.text.includes('.join("\\n"),'))!;
  const filterLine = m.after.find((x: any) => x.text.includes(".filter((section)"))!;
  const bodyStart = m.after.find((x: any) => x.text.trim() === "body: [")!;
  return edit("src/durable/present.ts", {
    revision: a.matches[0].revision,
    changes: [
      { kind: "replace", start: b.matches[0].anchor, content: "  call(args: unknown): { title: string; body?: string };" },
      { kind: "replace", start: m.anchor, end: joinLine.anchor, content: [
        "      title: call.label ?? (firstLine(call.code) || call.functionId || \"typescript\"),",
        "      ...(body === \"\" ? {} : { body }),",
      ].join("\n") },
      { kind: "insertBefore", anchor: "" + (Number(m.anchor.split(":")[0]) - 2) + ":" + "x" as any, content: "" },
    ].slice(0, 2) as any,
  }).then(async (r) => ({ r, bodyStart: bodyStart.text, filterLine: filterLine.text, a: a.matches[0].anchor }));
}
